// Erweiterte Spielansicht mit Filter, Ort und Sortierung
import {CommonModule} from '@angular/common';
import {FormsModule} from '@angular/forms';
import {Game} from '../../models/game.model';
import {Venue} from '../../models/venue.model';
import {TvzApiService} from '../../services/tvz-api.service';
import {Component, OnDestroy, OnInit} from '@angular/core';
import {Club} from '../../models/club.model';
import {InfoBoxComponent} from '../../components/info-box/info-box.component';
import {Router} from '@angular/router';
import {GeolocationService} from '../../services/geolocation.service';
import {SearchClubVenueComponent} from '../../components/search-club-venue/search-club-venue.component';
import {GameViewComponent} from '../../components/game-view/game-view.component';
import {GeolocationCoordinates} from '../../models/geolocation.models';

@Component({
  standalone: true,
  selector: 'app-game-list',
  templateUrl: './game-list-page.component.html',
  imports: [CommonModule, FormsModule, InfoBoxComponent, SearchClubVenueComponent, GameViewComponent],
})
export class GameListPageComponent implements OnInit, OnDestroy {
  games: Game[] = [];
  filtered: Game[] = [];
  selectedClub: Club | undefined;
  selectedVenue: Venue | undefined = undefined;
  currentLocation: GeolocationCoordinates | undefined;
  daysBefore = -14;
  daysAfter = 1;
  dateFrom: string = this.dateToInputFormat(this.daysAhead(-14));
  dateTo: string = this.dateToInputFormat(this.daysAhead(1));
  maxDistanceKm = 20;
  distanceFilterActive = false;

  constructor(private api: TvzApiService, protected geo: GeolocationService, private router: Router) {}

  ngOnInit() {
    this.geo.startTracking((location) => {
      if (location) {
        this.currentLocation = location.coords
        this.applyFilters()
      }
    })
  }

  ngOnDestroy() {
    this.geo.stopTracking()
  }

  loadGames() {
    if (this.selectedClub || this.selectedVenue) {
      this.api.getGames({
        club: this.selectedClub?.clubId,
        venue: this.selectedVenue?.venueId,
        season: this.api.getSeasonId() ?? undefined,
      }).subscribe(allGames => {
        this.games = allGames;
        this.applyFilters();
      });
    } else {
      this.games = [];
      this.filtered = [];
    }
  }

  daysAhead(n: number): Date {
    const d = new Date();
    d.setDate(d.getDate() + n);
    return d;
  }

  dateToInputFormat(d: Date): string {
    return d.toISOString().split('T')[0];
  }

  getDateFrom(): Date {
    return this.shiftDate(new Date(), this.daysBefore);
  }

  getDateTo(): Date {
    return this.shiftDate(new Date(), this.daysAfter);
  }

  shiftDate(base: Date, offsetDays: number): Date {
    const d = new Date(base);
    d.setDate(d.getDate() + offsetDays);
    return d;
  }

  getRangeBackground(value: number, min:number, max: number, inverted: boolean) {
    if (inverted) {
      const percent = ((value - min) / (max - min)) * 100;
      return `linear-gradient(to right, #d1d5db ${percent}%, #3b82f6 ${percent}%)`;
    } else {
      const percent = 100 - ((value - min) / (max - min)) * 100;
      return `linear-gradient(to left, #d1d5db ${percent}%, #3b82f6 ${percent}%)`;
    }
  }

  clubOrVenueSelected(data?: { venue?: Venue | undefined; club?: Club | undefined }) {
    this.selectedClub = data?.club
    this.selectedVenue = data?.venue
    this.loadGames()
  }

  applyFilters() {
    this.filtered = this.games.filter(game => {
      const from = new Date(this.dateFrom)
      const to = new Date(this.dateTo)
      const date = new Date(game.gameDateTime);
      const inDateRange = date >= from && date <= to;

      const venue = this.selectedVenue;
      const nearby = !this.distanceFilterActive || !this.geo.userLocation || !venue?.venueLat || !venue?.venueLon ||
        this.geo.getDistance(this.geo.userLocation, {
          lat: +venue.venueLat,
          lon: +venue.venueLon
        }) <= this.maxDistanceKm;
      return inDateRange && nearby;
    });
    this.filtered.sort((a, b) => new Date(a.gameDateTime).getTime() - new Date(b.gameDateTime).getTime());
  }

  sliderChanged() {
    this.dateFrom = this.dateToInputFormat(this.daysAhead(this.daysBefore));
    this.dateTo = this.dateToInputFormat(this.daysAhead(this.daysAfter));
    this.applyFilters();
  }

  daysBetween(first: string, second: string) {
    const oneDay = 24 * 60 * 60 * 1000;
    const firstDate = new Date(first);
    const secondDate = new Date(second);
    return Math.round((secondDate.getTime() - firstDate.getTime()) / oneDay);
  }

  dateSelectionChanged() {
    const today = new Date().toISOString().split('T')[0];

    this.daysBefore = this.daysBetween(today, this.dateFrom);
    this.daysAfter = this.daysBetween(today, this.dateTo);
    this.applyFilters()
  }

  toggleDistanceFilter() {
    this.distanceFilterActive = !this.distanceFilterActive;
  }

  selectGame(game: Game) {
    this.router.navigate(['/game', game.objectId]).then(() => {});
  }
};
